def transform(grid):
    height = len(grid)
    width = len(grid[0])
    colored_rows = [r for r, row in enumerate(grid) if any(row)]
    if not colored_rows:
        return [row[:] for row in grid]
    bottom = max(colored_rows)
    out = [[0 for _ in range(width)] for _ in range(height)]
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, color in enumerate(row):
            if color:
                new_c = c + shift
                if 0 <= new_c < width:
                    out[r][new_c] = color
    return out
